  {p₂ : β → δ} {g : γ → δ},
  (∀ (a : α), p₂ (f a) = g (p₁ a)) → Set.BijOn f s t → Set.InjOn g (p₁ '' s) → Set.BijOn g (p₁ '' s) (p₂ '' t)

